#!/usr/bin/env python3
"""Literal UTF-8 search, confined to a caller-approved root (POSIX)."""
import json
import os
import stat
import sys


class InvalidInput(Exception):
    pass


def search(data):
    invalid = {'error': 'invalid_input'}
    if not isinstance(data, dict) or set(data) != {'root', 'query', 'path'}:
        return invalid
    if any(not isinstance(data[k], str) for k in data):
        return invalid
    if not data['root'] or not data['query']:
        return invalid
    if '\x00' in data['root'] or '\x00' in data['path']:
        return invalid
    if not hasattr(os, 'O_NOFOLLOW'):
        return invalid

    directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
    file_flags = os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK
    matches = []

    def scan_file(fd, name):
        # Validate the complete file before emitting any matches.
        with os.fdopen(os.dup(fd), 'rb') as stream:
            raw = stream.read()
        try:
            content = raw.decode('utf-8')
        except UnicodeDecodeError:
            return
        for number, line in enumerate(content.splitlines(), 1):
            if data['query'] in line:
                matches.append({'path': name, 'line': number, 'text': line})

    def visit(parent_fd, entry, name, explicit=False):
        info = os.stat(entry, dir_fd=parent_fd, follow_symlinks=False)
        if stat.S_ISDIR(info.st_mode):
            flags = directory_flags
        elif stat.S_ISREG(info.st_mode):
            flags = file_flags
        else:
            if explicit:
                raise InvalidInput()
            return
        fd = os.open(entry, flags, dir_fd=parent_fd)
        try:
            opened = os.fstat(fd)
            if (opened.st_dev, opened.st_ino) != (info.st_dev, info.st_ino):
                raise InvalidInput()
            if stat.S_ISDIR(opened.st_mode):
                walk(fd, name)
            elif stat.S_ISREG(opened.st_mode):
                scan_file(fd, name)
            else:
                raise InvalidInput()
        finally:
            os.close(fd)

    def walk(fd, prefix):
        for entry in sorted(os.listdir(fd)):
            name = prefix + '/' + entry if prefix else entry
            visit(fd, entry, name)

    fds = []
    try:
        root = os.path.realpath(os.path.abspath(data['root']))
        requested = data['path'] or '.'
        # Absolute paths must be lexically within the canonical root.
        if os.path.isabs(requested):
            if os.path.commonpath([root, requested]) != root:
                raise InvalidInput()
            requested = os.path.relpath(requested, root)
        parts = [p for p in requested.split('/') if p not in ('', '.')]
        # Reject parent traversal even if later components re-enter the root.
        if '..' in parts:
            raise InvalidInput()
        fd = os.open(root, directory_flags)
        fds.append(fd)
        for part in parts[:-1]:
            fd = os.open(part, directory_flags, dir_fd=fd)
            fds.append(fd)
        if parts:
            visit(fd, parts[-1], '/'.join(parts), explicit=True)
        else:
            walk(fd, '')
        matches.sort(key=lambda item: (item['path'], item['line']))
        return {'matches': matches}
    except (OSError, ValueError, UnicodeError, InvalidInput):
        return invalid
    finally:
        for fd in reversed(fds):
            os.close(fd)


def main():
    try:
        data = json.load(sys.stdin)
    except (ValueError, UnicodeError):
        result = {'error': 'invalid_input'}
    else:
        result = search(data)
    json.dump(result, sys.stdout, ensure_ascii=True)
    sys.stdout.write('\n')


if __name__ == '__main__':
    main()
